css:
.d-table-group-toggle{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-table-group-toggle *,.d-table-group-toggle *::before,.d-table-group-toggle *::after{box-sizing:border-box}
.d-table-group-toggle [hidden]{display:none!important}
.d-table-group-toggle .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-table-group-toggle .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-table-group-toggle label{display:block;margin:8px 0}
.d-table-group-toggle input,.d-table-group-toggle select,.d-table-group-toggle textarea,.d-table-group-toggle button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-table-group-toggle input:not([type=checkbox]):not([type=radio]),.d-table-group-toggle select,.d-table-group-toggle textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-table-group-toggle button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-table-group-toggle button:disabled{opacity:.5;cursor:default}
.d-table-group-toggle :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-table-group-toggle [aria-invalid=true]{border-color:var(--warn)!important}
.d-table-group-toggle .d-scroll{max-width:100%;overflow:auto}
.d-table-group-toggle table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-table-group-toggle th,.d-table-group-toggle td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-table-group-toggle caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-table-group-toggle progress{width:100%;accent-color:var(--ink)}
.d-table-group-toggle pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-table-group-toggle h3,.d-table-group-toggle p{margin:8px 0}
.d-table-group-toggle [aria-pressed=true],.d-table-group-toggle [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-table-group-toggle .d-grow{flex:1;min-width:100px}
.d-table-group-toggle summary{cursor:pointer;padding:6px 0}
.d-table-group-toggle ul,.d-table-group-toggle ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{qa('[data-group]').forEach(button=>button.onclick=()=>{const expanded=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(expanded));qa('[data-in]').filter(row=>row.dataset.in===button.dataset.group).forEach(row=>row.hidden=!expanded);say(button.textContent+(expanded?'已展开':'已收起'));});})(root, q, qa, say);
}
